import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const rootDir = path.resolve(__dirname, '..')

// 1. Collect all valid routes generated by the site
const validRoutes = new Set([
  '/',
  '/guide/',
  '/problems/',
  '/compare/',
  '/gsy/',
  '/about/',
  '/404/',
  '/manifest.json',
  '/logo.svg',
  '/og-image.svg',
  '/robots.txt',
  '/sitemap.xml',
  '/sitemap-index.xml',
  '/c0326462ec5e4f48b945c7ad2a4ef69d.txt',
])

function scanContentRoutes(dir, collectionName) {
  if (!fs.existsSync(dir)) return
  const files = fs.readdirSync(dir, { recursive: true })
  for (const file of files) {
    if (typeof file === 'string' && (file.endsWith('.md') || file.endsWith('.mdx'))) {
      const relPath = file.replace(/\\/g, '/').replace(/\.mdx?$/, '')
      const route = `/${collectionName}/${relPath}/`
      validRoutes.add(route)
    }
  }
}

scanContentRoutes(path.join(rootDir, 'src/content/guide'), 'guide')
scanContentRoutes(path.join(rootDir, 'src/content/problems'), 'problems')
scanContentRoutes(path.join(rootDir, 'src/content/compare'), 'compare')
scanContentRoutes(path.join(rootDir, 'src/content/gsy'), 'gsy')
scanContentRoutes(path.join(rootDir, 'src/content/about'), 'about')

console.log(`[INFO] Total valid routes discovered: ${validRoutes.size}`)

// 2. Link extraction regex
const mdLinkRegex = /\[([^\]]+)\]\(([^)]+)\)/g
const htmlLinkRegex = /href=["']([^"']+)["']/g

let totalCheckedLinks = 0
let brokenLinks = []
let funnelViolations = []

function checkFile(filePath, isGuideContent = false) {
  const content = fs.readFileSync(filePath, 'utf-8')
  const relPath = path.relative(rootDir, filePath).replace(/\\/g, '/')

  // Funnel check for /guide/
  if (isGuideContent) {
    // Strip YAML frontmatter
    const bodyContent = content.replace(/^---[\s\S]*?---/, '')
    if (bodyContent.includes('光速云') || bodyContent.includes('gsyvipaff') || bodyContent.includes('/gsy/')) {
      funnelViolations.push({
        file: relPath,
        issue: 'Contains mention of 光速云 / GSY / /gsy/ link in Tier 1 (/guide/) content body!',
      })
    }
  }

  // Extract all links
  const links = []
  let match
  while ((match = mdLinkRegex.exec(content)) !== null) {
    links.push({ text: match[1], url: match[2] })
  }
  while ((match = htmlLinkRegex.exec(content)) !== null) {
    links.push({ text: 'HTML link', url: match[1] })
  }

  for (const { text, url } of links) {
    // Skip anchor-only, external, mailto, tel, javascript
    if (url.startsWith('#') || url.startsWith('http://') || url.startsWith('https://') || url.startsWith('mailto:') || url.startsWith('javascript:')) {
      continue
    }

    totalCheckedLinks++
    // Clean query/hash
    const cleanUrl = url.split('#')[0].split('?')[0]
    // Normalize trailing slash
    const normalizedUrl = cleanUrl.endsWith('/') ? cleanUrl : cleanUrl + '/'

    if (!validRoutes.has(normalizedUrl) && !validRoutes.has(cleanUrl)) {
      brokenLinks.push({
        file: relPath,
        linkText: text,
        rawUrl: url,
        normalizedUrl,
      })
    }
  }
}

function scanDir(dir, isGuide = false) {
  if (!fs.existsSync(dir)) return
  const entries = fs.readdirSync(dir, { withFileTypes: true })
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      scanDir(fullPath, isGuide || entry.name === 'guide')
    } else if (entry.isFile() && (entry.name.endsWith('.md') || entry.name.endsWith('.astro'))) {
      const isGuideFile = isGuide || fullPath.includes('content\\guide') || fullPath.includes('content/guide')
      checkFile(fullPath, isGuideFile)
    }
  }
}

scanDir(path.join(rootDir, 'src/content'))
scanDir(path.join(rootDir, 'src/pages'))

console.log(`\n=== AUDIT RESULTS ===`)
console.log(`Total internal links checked: ${totalCheckedLinks}`)
console.log(`Broken internal links: ${brokenLinks.length}`)
if (brokenLinks.length > 0) {
  console.log('\nBroken Links Detail:')
  brokenLinks.forEach((b) => {
    console.log(`  File: ${b.file}`)
    console.log(`    Link Text: "${b.linkText}" -> Target: "${b.rawUrl}"`)
  })
}

console.log(`\nFunnel violations in /guide/: ${funnelViolations.length}`)
if (funnelViolations.length > 0) {
  console.log('\nFunnel Violations Detail:')
  funnelViolations.forEach((v) => {
    console.log(`  File: ${v.file}: ${v.issue}`)
  })
}

if (brokenLinks.length === 0 && funnelViolations.length === 0) {
  console.log('\n>>> ALL CHECKS PASSED PERFECTLY! 100% CLEAN INTERNAL LINKING & FUNNEL INTEGRITY <<<')
  process.exit(0)
} else {
  process.exit(1)
}
